import java.util.*;
public class Main {
    static long canFinishAt(int[] piles, int speed) {
        long hours = 0;
        for (int pile : piles) {
            hours += (pile + speed - 1L) / speed;
        }
        return hours;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int h = sc.nextInt();
        int[] piles = new int[n];
        int low = 1;
        int high = 0;
        for (int i = 0; i < n; i++) {
            piles[i] = sc.nextInt();
            high = Math.max(high, piles[i]);
        }
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (canFinishAt(piles, mid) <= h) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        System.out.println(low);
        sc.close();
    }
}
